UPDATE train_seat ts
INNER JOIN train_seat_class tsc
    ON ts.train_seat_class_id = tsc.id
INNER JOIN seat_class sc
    ON tsc.seat_class_id = sc.id
SET ts.status = CASE

        WHEN tsc.train_id = #{detail.trainId}
            AND sc.type = #{detail.seatType}
            AND tsc.carriage_number = #{detail.carriageNumber}
            AND ts.seat_no = #{detail.seatNo}
        THEN #{detail.status}

ELSE ts.status  -- 不匹配条件的记录保持原状态
END


        (tsc.train_id, sc.type, tsc.carriage_number, ts.seat_no) IN

            (#{detail.trainId}, #{detail.seatType}, #{detail.carriageNumber}, #{detail.seatNo})
